"""Dependency-free Coordinator strategy catalog page."""

from __future__ import annotations


def catalog_html() -> str:
    return """<!doctype html><html lang='zh-CN'><head><meta charset='utf-8'>
<meta name='viewport' content='width=device-width,initial-scale=1'><title>BigQMT 策略库</title>
<style>body{margin:0;background:#f5f7fb;color:#172033;font:14px 'Segoe UI','Microsoft YaHei',sans-serif}.wrap{max-width:1180px;margin:auto;padding:28px}.card{background:#fff;border:1px solid #e1e7ef;border-radius:12px;padding:20px;margin:14px 0;box-shadow:0 2px 8px #1e293b0a}h1{margin:0 0 6px}.muted{color:#64748b}.tag{display:inline-block;border-radius:999px;padding:5px 9px;margin:4px 4px 0 0;font-size:12px;background:#ecfdf3;color:#157a50}.lock{background:#fff7e5;color:#925d00}.row{display:grid;grid-template-columns:2fr 1fr 1fr 1fr;gap:12px;margin-top:15px}.cell{border:1px solid #e4e9f0;border-radius:8px;padding:10px;word-break:break-word}.targets{border-top:1px solid #edf0f4;margin-top:18px;padding-top:14px}.target{display:inline-flex;align-items:center;gap:6px;border:1px solid #dbe3ec;border-radius:8px;padding:8px 10px;margin:4px 6px 4px 0;background:#fbfdff}.target input{accent-color:#2563eb}.button{border:0;border-radius:8px;padding:9px 14px;background:#2563eb;color:#fff;cursor:pointer;margin:10px 8px 0 0}.button:disabled{background:#94a3b8;cursor:not-allowed}.preview{margin-top:12px;padding:12px;border-radius:8px;background:#f8fafc;white-space:pre-wrap}.ok{color:#157a50}.warn{color:#925d00}@media(max-width:720px){.row{grid-template-columns:1fr}}</style></head>
<body><main class='wrap'><div class='card'><h1>BigQMT 私有策略库</h1><div class='muted'>NAS 私有 candidate · 策略源码不进入 GitHub · 安装后不自动启动</div><div id='summary' class='muted'>读取中…</div></div><div id='list'></div></main>
<script>const root=document.getElementById('list'),summary=document.getElementById('summary');function hostLabel(id){const value=String(id||'未知主机');const last=value.split('.').pop();return ['105','113','125'].includes(last)?'.'+last:value}function showBox(section,text,good){const box=section.querySelector('.preview')||document.createElement('div');box.className='preview '+(good?'ok':'warn');box.textContent=text;section.append(box)}async function load(){try{const [cr,hr]=await Promise.all([fetch('/api/v1/strategy-candidates',{cache:'no-store'}),fetch('/api/v1/hosts',{cache:'no-store'})]);if(!cr.ok||!hr.ok)throw Error();const d=await cr.json(),hd=await hr.json(),hosts=Array.isArray(hd.hosts)?hd.hosts:[];summary.textContent=(d.library_available?'策略库在线':'策略库不可用')+' · '+(d.candidates||[]).length+' 个 candidate · Host Agent 拉取安装';root.replaceChildren();for(const x of d.candidates||[]){const c=document.createElement('section');c.className='card';const h=document.createElement('h2');h.textContent=x.strategy_id||'未知策略';c.append(h);const row=document.createElement('div');row.className='row';for(const v of [x.version||'-',x.build_id||'-',x.status||'-',x.manifest_sha256||'-']){const cell=document.createElement('div');cell.className='cell';cell.textContent=v;row.append(cell)}c.append(row);const safe=document.createElement('div');safe.innerHTML='<span class="tag">orders_enabled=false</span><span class="tag">formal_account_allowed=false</span><span class="tag lock">安装后不自动启动</span>';c.append(safe);const section=document.createElement('div');section.className='targets';const title=document.createElement('div');title.className='muted';title.textContent='选择目标托盘（先预览，再请求本地安装）';section.append(title);for(const host of hosts){const label=document.createElement('label');label.className='target';const input=document.createElement('input');input.type='checkbox';input.value=host.host_id||'';const text=document.createElement('span');text.textContent=hostLabel(host.host_id)+' · '+(host.state||'UNKNOWN');label.append(input,text);section.append(label)}if(!hosts.length){const empty=document.createElement('div');empty.className='muted';empty.textContent='暂无在线托盘心跳';section.append(empty)}const preview=document.createElement('button');preview.className='button';preview.textContent='生成推送预览';preview.onclick=async()=>{const selected=[...section.querySelectorAll('input:checked')].map(e=>e.value);preview.disabled=true;try{const response=await fetch('/api/v1/strategy-push-preview',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({strategy_id:x.strategy_id,version:x.version,build_id:x.build_id,target_host_ids:selected})});const data=await response.json();showBox(section,JSON.stringify(data,null,2),response.ok)}catch(e){showBox(section,'预览请求失败：Coordinator 不可达',false)}finally{preview.disabled=false}};section.append(preview);const install=document.createElement('button');install.className='button';install.textContent='请求安装（不启动）';install.onclick=async()=>{const selected=[...section.querySelectorAll('input:checked')].map(e=>e.value);install.disabled=true;try{const response=await fetch('/api/v1/strategy-install-request',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({strategy_id:x.strategy_id,version:x.version,build_id:x.build_id,target_host_ids:selected,requested_by:'dashboard'})});const data=await response.json();showBox(section,JSON.stringify(data,null,2),response.ok)}catch(e){showBox(section,'安装请求失败：Coordinator 不可达',false)}finally{install.disabled=false}};section.append(install);c.append(section);root.append(c)}}catch(e){summary.textContent='策略库读取失败';root.textContent='Coordinator 暂不可达'}}load();setInterval(load,10000)</script></body></html>"""

